public sealed partial class LogReq : IProtoMessage
{
    public MsgType Type => MsgType.Log;
    public bool IsResponse => false;

    public LogLevel? Level { get; set; }
    public string? Tag { get; set; }
    public string? Text { get; set; }
    public ulong? TsMs { get; set; }

    public void Write(TlvWriter w)
    {
        if (Level != null) w.U8(0x01, (byte)Level.Value);
        if (Tag != null) w.Str(0x02, Tag, 16);
        if (Text != null) w.Str(0x03, Text, 200);
        if (TsMs != null) w.U64(0x04, TsMs.Value);
    }

    public static LogReq Read(System.ReadOnlySpan<byte> data)
    {
        var m = new LogReq();
        var r = new TlvReader(data);
        while (r.Next(out var tag, out var v))
        {
            switch (tag & 0x7F)
            {
                case 1: m.Level = (LogLevel)Tlv.U8(v); break;
                case 2: m.Tag = Tlv.Str(v); break;
                case 3: m.Text = Tlv.Str(v); break;
                case 4: m.TsMs = Tlv.U64(v); break;
                default: Tlv.Unknown(tag); break;
            }
        }
        return m;
    }
}

